Matrix features = Matrix.fromRows(new double[][]{
        {0.0, 1.0}, {1.0, 1.5}, {9.0, 8.5}, {8.5, 9.0}});
KMeans model = KMeans.builder().clusters(2).build().fit(features);

Path file = Path.of("kmeans.jsl");
ModelCodec.save(file, model);
KMeans restored = ModelCodec.load(file, KMeans.class);
long bytes = ModelCodec.fileSize(file);

Matrix x = Matrix.fromRows(new double[][]{
        {0.0, 1.0}, {1.0, 1.5}, {9.0, 8.5}, {8.5, 9.0}});
double[] y = {0.0, 0.0, 1.0, 1.0};
LinearRegression model = LinearRegression.builder().build().fit(x, y);

Path file = Path.of("linear.onnx");
OnnxConverter.export(model, 2, file);

OnnxModel onnx = OnnxConverter.load(file);
int features = onnx.inputs().get(0).shape()[1];
Matrix scores = onnx.predictMatrix(x);

Path file = Path.of("model.onnx");
OnnxModel model = OnnxModel.load(file);

for (OnnxModel.ValueInfo in : model.inputs()) {
    System.out.println(in.name() + " " + java.util.Arrays.toString(in.shape()));
}
System.out.println(model.opsetVersion() + " / " + model.nodes().size());

Matrix features = Matrix.fromRows(new double[][]{{
        1.0, 2.0}, {3.0, 4.0}});
Matrix scores = model.predictMatrix(features);

byte[] encoded = model.toBytes();
model.save(Path.of("copy.onnx"));
